import yaml
d=yaml.safe_load(open('docs/reviews/pvc/2026-11-24_standard-1-2-0.pvc.yaml'))
print(list(d.keys()))
for k,v in d.items():
    if isinstance(v,(str,int,float)): print(k,':',str(v)[:300])
checks=d.get('checks') or d.get('results')
if isinstance(checks,list):
    for c in checks: print(c.get('id'),c.get('status'),(c.get('title') or c.get('name') or '')[:80])
acts=d.get('actions') or []
p1=[a for a in acts if a.get('priority')=='P1']
print(len(acts),len(p1))
for a in p1[:40]: print('-',(a.get('action') or a.get('title') or a.get('description'))[:160])
EOF

